/**
 * Qatar Unseen — map engine.
 *
 * Owns the selection state (which localities and which municipalities are
 * marked) and renders the SVG map. The checklist in the sidebar is rendered by
 * PHP, because it is static content; this file only flips its aria-checked
 * attributes, so there is one owner per thing and no duplicated list to drift.
 *
 * Coordinate data comes from assets/data/{geo,localities}.json, generated by
 * setup/prepare.php. Nothing here does projection maths — the x/y in
 * localities.json are already SVG user units.
 *
 * Public surface: window.QMap
 */
(function () {
  'use strict';

  const SVGNS   = 'http://www.w3.org/2000/svg';
  const STORE   = 'qatar-unseen-v1';
  const VB      = 1000;          // viewBox is 0 0 1000 1000
  const MAX_K   = 9;
  const DRAG_PX = 5;             // movement beyond this counts as a drag, not a tap

  // --------------------------------------------------------------- state --

  const S = {
    places:  new Set(),   // locality slugs
    regions: new Set(),   // municipality codes
    name:    '',
    theme:   'maroon',
    photo:   null,        // data URL, kept client-side until a link is made
  };

  let GEO = null;         // geo.json
  let LOCS = [];          // localities.json
  let THEMES = {};        // share_themes rows, keyed by slug
  let BY_SLUG = {};
  let BY_MUN  = {};
  let LANG = 'en';        // which of the name_en / name_ar columns to show

  /** The municipality or locality name in the visitor's language. */
  function nm(row) {
    return row['name_' + LANG] || row.name_en || '';
  }

  const subs = [];        // change subscribers

  let svg, layer, elPaths = {}, elDots = {}, elHit = {}, elLabels = {};
  let view = { k: 1, x: 0, y: 0 };
  let HOME = { k: 1, x: 0, y: 0 };   // filled in once the geometry is known
  let BOUNDS = [0, 0, VB, VB];       // union bbox of the municipalities

  /** Union of every municipality's bounding box — the country, not the canvas. */
  function geoBounds(geo) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const code in geo.municipalities) {
      const b = geo.municipalities[code].bbox;
      if (!b || b.length !== 4) continue;
      x0 = Math.min(x0, b[0]); y0 = Math.min(y0, b[1]);
      x1 = Math.max(x1, b[2]); y1 = Math.max(y1, b[3]);
    }
    return isFinite(x0) ? [x0, y0, x1, y1] : [0, 0, VB, VB];
  }

  /**
   * The default framing: the 1000x1000 canvas has a lot of empty sea, so open
   * zoomed to the country with a little breathing room rather than to 1:1.
   * Kept as a transform rather than a tighter viewBox so the pan clamp below
   * stays a two-line calculation.
   */
  function computeHome() {
    BOUNDS = geoBounds(GEO);
    const [x0, y0, x1, y1] = BOUNDS;
    const w = Math.max(1, x1 - x0), h = Math.max(1, y1 - y0);
    const pad = 0.06;                        // 6% margin around the coast
    // No upper cap below MAX_K: the canvas is wider than the country, so this
    // is normally a zoom *in* (k > 1), not a zoom out.
    const k = Math.min(MAX_K, VB / (Math.max(w, h) * (1 + pad * 2)));
    HOME = { k: k, x: VB / 2 - k * (x0 + w / 2), y: VB / 2 - k * (y0 + h / 2) };
    view = { k: HOME.k, x: HOME.x, y: HOME.y };
  }

  // ------------------------------------------------------------- storage --

  function load() {
    let raw = null;
    try { raw = localStorage.getItem(STORE); } catch (e) { return; }
    if (!raw) return;
    try {
      const d = JSON.parse(raw);
      if (Array.isArray(d.places))   d.places.forEach(s => { if (BY_SLUG[s]) S.places.add(s); });
      if (Array.isArray(d.regions))  d.regions.forEach(c => { if (GEO.municipalities[c]) S.regions.add(c); });
      if (typeof d.name  === 'string') S.name  = d.name.slice(0, 48);
      if (typeof d.theme === 'string' && THEMES[d.theme]) S.theme = d.theme;
      if (typeof d.photo === 'string' && d.photo.startsWith('data:image/')) S.photo = d.photo;
    } catch (e) { /* corrupt or from an older shape — start clean */ }
  }

  let saveTimer = null;
  function save() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(function () {
      try {
        localStorage.setItem(STORE, JSON.stringify({
          places:  Array.from(S.places),
          regions: Array.from(S.regions),
          name:    S.name,
          theme:   S.theme,
          photo:   S.photo,
        }));
      } catch (e) { /* quota full or storage disabled — the session still works */ }
    }, 250);
  }

  function emit() {
    save();
    for (const fn of subs) { try { fn(api); } catch (e) { console.error(e); } }
    document.dispatchEvent(new CustomEvent('qmap:change', { detail: api }));
  }

  // ------------------------------------------------------------ rendering --

  function el(name, attrs) {
    const n = document.createElementNS(SVGNS, name);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    return n;
  }

  function build() {
    svg = el('svg', {
      viewBox: '0 0 ' + VB + ' ' + VB,
      role: 'img',
      'aria-label': 'Map of Qatar',
    });

    layer = el('g', { id: 'layer' });
    const gRegions = el('g', { id: 'regions' });
    const gLabels  = el('g', { id: 'labels' });
    const gDots    = el('g', { id: 'dots' });

    for (const code in GEO.municipalities) {
      const m = GEO.municipalities[code];

      const p = el('path', { class: 'mun-path', d: m.d, 'data-code': code, tabindex: '0' });
      p.setAttribute('role', 'button');
      p.setAttribute('aria-label', nm(m));
      gRegions.appendChild(p);
      elPaths[code] = p;

      const t = el('text', { class: 'mun-label', x: m.label.x, y: m.label.y, 'text-anchor': 'middle' });
      t.textContent = nm(m);
      gLabels.appendChild(t);
      elLabels[code] = t;
    }

    // Hit discs are appended first so a dot is never buried under a neighbour's
    // (invisible, and much larger) tap target.
    const hits = [];
    for (const l of LOCS) {
      const h = el('circle', { class: 'loc-hit', cx: l.x, cy: l.y, 'data-slug': l.slug });
      hits.push(h);
      elHit[l.slug] = h;
    }
    hits.forEach(h => gDots.appendChild(h));

    for (const l of LOCS) {
      const d = el('circle', { class: 'loc-dot', cx: l.x, cy: l.y, 'data-slug': l.slug });
      const t = el('title', {});
      t.textContent = nm(l);
      d.appendChild(t);
      gDots.appendChild(d);
      elDots[l.slug] = d;
    }

    layer.appendChild(gRegions);
    layer.appendChild(gLabels);
    layer.appendChild(gDots);
    svg.appendChild(layer);
  }

  // --------------------------------------------------------------- paint --

  function paint() {
    for (const code in elPaths) {
      const on = S.regions.has(code);
      elPaths[code].classList.toggle('on', on);
      elPaths[code].setAttribute('aria-pressed', on ? 'true' : 'false');
      elLabels[code].classList.toggle('on', on);
    }
    for (const l of LOCS) {
      const on = S.places.has(l.slug);
      elDots[l.slug].classList.toggle('on', on);
      elDots[l.slug].setAttribute('aria-pressed', on ? 'true' : 'false');
    }
    paintTheme();
  }

  function paintTheme() {
    const th = THEMES[S.theme] || THEMES[Object.keys(THEMES)[0]];
    if (!th) return;
    svg.style.setProperty('--m-land',  th.land);
    svg.style.setProperty('--m-on',    th.visited);
    svg.style.setProperty('--m-hover', 'color-mix(in srgb, ' + th.land + ' 82%, ' + th.ink + ')');
    svg.style.setProperty('--m-label', th.ink_soft || th.ink);
    document.body.setAttribute('data-theme-slug', S.theme);
  }

  /** Name shown on the card, falling back to a generic label. */
  function displayName() {
    const n = (S.name || '').trim();
    return n !== '' ? n : null;
  }

  // ------------------------------------------------------------- gestures --

  let pointers = new Map();
  let dragging = false;
  let moved = 0;
  let last = null;
  let downTarget = null;      // what was under the finger when it landed
  let pinchStart = 0, pinchK = 1;

  /** Screen point -> SVG user coordinates. */
  function toUser(ev) {
    const pt = svg.createSVGPoint();
    pt.x = ev.clientX;
    pt.y = ev.clientY;
    const m = svg.getScreenCTM();
    return m ? pt.matrixTransform(m.inverse()) : { x: 0, y: 0 };
  }

  /**
   * Keep the country on screen. When the scaled content is wider than the
   * viewport we let the user pan across it; when it is narrower we pin it
   * centred, which is the case at the default zoom.
   */
  function clampView() {
    const [x0, y0, x1, y1] = BOUNDS;
    view.x = clampAxis(view.x, x0, x1);
    view.y = clampAxis(view.y, y0, y1);
  }

  function clampAxis(t, lo, hi) {
    const span = (hi - lo) * view.k;
    if (span >= VB) {
      return Math.min(-view.k * lo, Math.max(VB - view.k * hi, t));
    }
    return (VB - span) / 2 - view.k * lo;
  }

  function applyView() {
    layer.setAttribute('transform',
      'translate(' + view.x.toFixed(2) + ' ' + view.y.toFixed(2) + ') scale(' + view.k.toFixed(4) + ')');

    // Counter-scale dots and labels so they keep a comfortable on-screen size
    // instead of ballooning into blobs at 9x. Normalised against the home zoom
    // so a card at rest shows dots at exactly the size the CSS asks for.
    const s = Math.sqrt(Math.max(1e-6, view.k / HOME.k));
    svg.style.setProperty('--dot-r',  Math.max(2.2, 5.5 / s).toFixed(2) + 'px');
    svg.style.setProperty('--dot-sw', Math.max(1.1, 2.2 / s).toFixed(2) + 'px');
    svg.style.setProperty('--lbl-fs', Math.max(5.5, 13 / s).toFixed(2) + 'px');
    svg.style.setProperty('--lbl-sw', Math.max(1.2, 3 / s).toFixed(2) + 'px');
  }

  function zoomAt(userX, userY, factor) {
    const k2 = Math.min(MAX_K, Math.max(HOME.k, view.k * factor));
    if (k2 === view.k) return;
    const s = k2 / view.k;
    view.x = userX - s * (userX - view.x);
    view.y = userY - s * (userY - view.y);
    view.k = k2;
    clampView();
    applyView();
  }

  function resetView() {
    view = { k: HOME.k, x: HOME.x, y: HOME.y };
    applyView();
  }

  function bindGestures() {
    const frame = svg.parentNode;
    const TARGETS = '[data-slug], [data-code]';

    frame.addEventListener('wheel', function (e) {
      // At rest, a downward scroll belongs to the page — trapping it would make
      // the map a scroll bar the visitor cannot get past. Zooming in (and any
      // deliberate scroll while already zoomed) is ours.
      if (e.deltaY > 0 && view.k <= HOME.k + 1e-6) return;

      e.preventDefault();
      const u = toUser(e);
      zoomAt(u.x, u.y, e.deltaY < 0 ? 1.14 : 1 / 1.14);
    }, { passive: false });

    svg.addEventListener('pointerdown', function (e) {
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (pointers.size === 1) {
        dragging = true;
        moved = 0;
        last = { x: e.clientX, y: e.clientY };
        // Remembered, because setPointerCapture would otherwise retarget the
        // follow-up click at the <svg> and lose which shape was tapped.
        downTarget = e.target.closest ? e.target.closest(TARGETS) : null;
      } else if (pointers.size === 2) {
        dragging = false;
        pinchStart = pinchDist();
        pinchK = view.k;
      }
    });

    svg.addEventListener('pointermove', function (e) {
      if (!pointers.has(e.pointerId)) return;
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (pointers.size >= 2) {
        const d = pinchDist();
        if (pinchStart > 0 && d > 0) {
          const c = pinchCentre();
          const u = toUser({ clientX: c.x, clientY: c.y });
          zoomAt(u.x, u.y, (pinchK * (d / pinchStart)) / view.k);
        }
        return;
      }

      if (!dragging || !last) return;
      const dx = e.clientX - last.x;
      const dy = e.clientY - last.y;
      moved += Math.abs(dx) + Math.abs(dy);
      if (moved < DRAG_PX) return;

      if (!svg.hasPointerCapture(e.pointerId)) {
        // Capture only once a drag is real, so plain taps keep their target.
        try { svg.setPointerCapture(e.pointerId); } catch (err) { /* not fatal */ }
        svg.classList.add('dragging');
      }

      const rect = svg.getBoundingClientRect();
      const scale = VB / (rect.width || VB);
      view.x += dx * scale;
      view.y += dy * scale;
      clampView();
      applyView();
      last = { x: e.clientX, y: e.clientY };
    });

    function endPointer(e) {
      pointers.delete(e.pointerId);
      if (pointers.size === 0) {
        dragging = false;
        last = null;
        pinchStart = 0;
        svg.classList.remove('dragging');
      }
    }
    svg.addEventListener('pointerup', endPointer);
    svg.addEventListener('pointercancel', endPointer);

    svg.addEventListener('click', function (e) {
      if (moved >= DRAG_PX) { moved = 0; downTarget = null; return; }
      const target = (e.target.closest && e.target.closest(TARGETS)) || downTarget;
      downTarget = null;
      if (!target) return;

      // Inside a zoomed-out map a tap on a dot's hit disc is unambiguous; the
      // hit disc is separate from the visible dot so this stays true at 9x.
      const slug = target.getAttribute('data-slug');
      if (slug) { togglePlace(slug); return; }
      const code = target.getAttribute('data-code');
      if (code) toggleRegion(code);
    });

    svg.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      const code = e.target.getAttribute && e.target.getAttribute('data-code');
      if (code) { e.preventDefault(); toggleRegion(code); }
    });

    svg.addEventListener('dblclick', function (e) {
      e.preventDefault();
      const u = toUser(e);
      zoomAt(u.x, u.y, view.k > 2 ? 1 / view.k : 1.8);
    });

    function pinchDist() {
      const p = Array.from(pointers.values());
      return Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y);
    }
    function pinchCentre() {
      const p = Array.from(pointers.values());
      return { x: (p[0].x + p[1].x) / 2, y: (p[0].y + p[1].y) / 2 };
    }
  }

  // --------------------------------------------------------------- toggles --

  function togglePlace(slug, force) {
    if (!BY_SLUG[slug]) return;
    const want = force === undefined ? !S.places.has(slug) : !!force;
    if (want) S.places.add(slug); else S.places.delete(slug);
    syncRow(slug, want);
    elDots[slug].classList.toggle('on', want);
    elDots[slug].setAttribute('aria-pressed', want ? 'true' : 'false');
    emit();
  }

  function toggleRegion(code, force) {
    if (!GEO.municipalities[code]) return;
    const want = force === undefined ? !S.regions.has(code) : !!force;
    if (want) S.regions.add(code); else S.regions.delete(code);
    elPaths[code].classList.toggle('on', want);
    elPaths[code].setAttribute('aria-pressed', want ? 'true' : 'false');
    elLabels[code].classList.toggle('on', want);
    syncMunHead(code, want);
    emit();
  }

  /** Mark every locality in one municipality at once. */
  function toggleMunicipalityPlaces(code, force) {
    const list = BY_MUN[code] || [];
    if (!list.length) return;
    const all = list.every(l => S.places.has(l.slug));
    const want = force === undefined ? !all : !!force;
    list.forEach(l => {
      if (want) S.places.add(l.slug); else S.places.delete(l.slug);
      elDots[l.slug].classList.toggle('on', want);
      elDots[l.slug].setAttribute('aria-pressed', want ? 'true' : 'false');
      syncRow(l.slug, want);
    });
    emit();
  }

  function selectAll() {
    LOCS.forEach(l => S.places.add(l.slug));
    Object.keys(GEO.municipalities).forEach(c => S.regions.add(c));
    paint(); syncAllRows();
    emit();
  }

  function clearAll() {
    S.places.clear();
    S.regions.clear();
    paint(); syncAllRows();
    emit();
  }

  // ---------------------------------------------------------- sidebar sync --

  function syncRow(slug, on) {
    const row = document.querySelector('.loc-row[data-slug="' + cssEsc(slug) + '"]');
    if (row) row.setAttribute('aria-checked', on ? 'true' : 'false');
    const head = munHeadFor(slug);
    if (head) updateMunCount(head);
  }

  function syncMunHead(code, on) {
    const head = document.querySelector('.mun-head[data-code="' + cssEsc(code) + '"]');
    if (head) {
      head.setAttribute('aria-checked', on ? 'true' : 'false');
      const sw = head.querySelector('.swatch');
      if (sw) sw.classList.toggle('on', on);
    }
    updateMunCount(head);
  }

  function munHeadFor(slug) {
    const loc = BY_SLUG[slug];
    if (!loc) return null;
    const group = document.querySelector('.mun-group[data-code="' + cssEsc(loc.mun) + '"]');
    return group ? group.querySelector('.mun-head') : null;
  }

  /** Refresh the "12 / 14" badge on a municipality's checklist row. */
  function updateMunCount(head) {
    if (!head) return;
    const code = head.getAttribute('data-code');
    const list = BY_MUN[code] || [];
    const done = list.filter(l => S.places.has(l.slug)).length;
    const out = head.querySelector('.count');
    if (out) out.textContent = done + ' / ' + list.length;
  }

  function syncAllRows() {
    document.querySelectorAll('.loc-row[data-slug]').forEach(function (row) {
      row.setAttribute('aria-checked', S.places.has(row.getAttribute('data-slug')) ? 'true' : 'false');
    });
    document.querySelectorAll('.mun-head[data-code]').forEach(function (head) {
      const code = head.getAttribute('data-code');
      const on = S.regions.has(code);
      head.setAttribute('aria-checked', on ? 'true' : 'false');
      const sw = head.querySelector('.swatch');
      if (sw) sw.classList.toggle('on', on);
      updateMunCount(head);
    });
  }

  function cssEsc(s) { return String(s).replace(/["\\]/g, '\\$&'); }

  // -------------------------------------------------------------- sidebar --

  let sidebarBound = false;

  /**
   * One delegated listener for the whole checklist. Order matters: the fold
   * and mark-all controls sit inside the municipality header, so they have to
   * be claimed before the header's own click-to-colour handler sees them.
   */
  function bindSidebar() {
    if (sidebarBound) return;   // delegated listeners live on document, so twice = double toggles
    sidebarBound = true;

    document.addEventListener('click', function (e) {
      if (!e.target.closest) return;

      const fold = e.target.closest('[data-fold]');
      if (fold) {
        const g = fold.closest('.mun-group');
        if (g) g.setAttribute('data-open', g.getAttribute('data-open') === '1' ? '0' : '1');
        return;
      }

      const all = e.target.closest('[data-mark-all]');
      if (all) { toggleMunicipalityPlaces(all.getAttribute('data-mark-all')); return; }

      const head = e.target.closest('.mun-head[data-code]');
      if (head) { toggleRegion(head.getAttribute('data-code')); return; }

      const row = e.target.closest('.loc-row[data-slug]');
      if (row) { togglePlace(row.getAttribute('data-slug')); return; }
    });

    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      if (!e.target.closest) return;
      const row = e.target.closest('.loc-row[data-slug]');
      if (row) { e.preventDefault(); togglePlace(row.getAttribute('data-slug')); }
    });
  }

  // ---------------------------------------------------------------- search --

  /**
   * Search text for a locality, built once per page load.
   *
   * It mixes the data with the checklist row's own rendered text on purpose:
   * the kind tag is translated ("مدينة", not "city") and an Arabic name has no
   * Latin spelling, so anything the user can read in the list has to be
   * findable — otherwise the map and the list disagree about a match and rows
   * vanish while their dots stay lit.
   */
  let HAY = null;
  function hay(slug) {
    if (!HAY) {
      HAY = {};
      LOCS.forEach(function (l) {
        HAY[l.slug] = [l.name_en, l.name_ar, l.kind, l.slug].join(' ').toLowerCase();
      });
      document.querySelectorAll('.loc-row[data-slug]').forEach(function (row) {
        const s = row.getAttribute('data-slug');
        if (HAY[s] !== undefined) HAY[s] += ' ' + row.textContent.toLowerCase();
      });
    }
    return HAY[slug] || '';
  }

  /** Hide dots and checklist rows that do not match; '' shows everything. */
  function filter(q) {
    const needle = q.trim().toLowerCase();
    let shown = 0;
    const perMun = {};

    LOCS.forEach(function (l) {
      const hit = needle === '' || hay(l.slug).indexOf(needle) !== -1;
      if (hit) { shown++; perMun[l.mun] = (perMun[l.mun] || 0) + 1; }
      elDots[l.slug].classList.toggle('hidden', !hit);
      elHit[l.slug].classList.toggle('hidden', !hit);
    });

    document.querySelectorAll('.loc-row[data-slug]').forEach(function (row) {
      const slug = row.getAttribute('data-slug');
      row.hidden = !(needle === '' || hay(slug).indexOf(needle) !== -1);
    });

    // Open any group that has a match, so results are never hidden behind a
    // collapsed header; leave groups alone while the box is empty.
    if (needle !== '') {
      document.querySelectorAll('.mun-group[data-code]').forEach(function (g) {
        const code = g.getAttribute('data-code');
        g.hidden = !perMun[code];
        g.setAttribute('data-open', perMun[code] ? '1' : '0');
      });
    } else {
      document.querySelectorAll('.mun-group[data-code]').forEach(function (g) {
        g.hidden = false;
      });
    }

    return shown;
  }

  // ------------------------------------------------------------ public API --

  const api = {
    get state()   { return S; },
    get geo()     { return GEO; },
    get localities() { return LOCS; },
    get themes()  { return THEMES; },

    counts: function () {
      return {
        places:  S.places.size,
        total:   LOCS.length,
        regions: S.regions.size,
        regionsTotal: Object.keys(GEO.municipalities).length,
      };
    },

    /** Slug list in map order — the stable form that gets saved and shared. */
    marked: function () { return LOCS.filter(l => S.places.has(l.slug)).map(l => l.slug); },
    markedRegions: function () { return Object.keys(GEO.municipalities).filter(c => S.regions.has(c)); },

    togglePlace, toggleRegion, toggleMunicipalityPlaces,
    selectAll, clearAll, filter, resetView,

    setTheme: function (slug) {
      if (!THEMES[slug]) return;
      S.theme = slug;
      paintTheme();
      emit();
    },

    setName: function (v) {
      S.name = String(v || '').slice(0, 48);
      emit();
    },

    setPhoto: function (dataUrl) {
      S.photo = dataUrl || null;
      emit();
    },

    displayName: displayName,
    theme: function () { return THEMES[S.theme] || THEMES[Object.keys(THEMES)[0]]; },
    viewBox: function () { return VB; },

    onChange: function (fn) { subs.push(fn); return function () { const i = subs.indexOf(fn); if (i >= 0) subs.splice(i, 1); }; },

    init: function (cfg) {
      GEO    = cfg.geo;
      LOCS   = cfg.localities;
      THEMES = cfg.themes;
      LANG   = cfg.lang === 'ar' ? 'ar' : 'en';

      LOCS.forEach(function (l) { BY_SLUG[l.slug] = l; (BY_MUN[l.mun] = BY_MUN[l.mun] || []).push(l); });

      computeHome();
      build();
      load();

      const frame = document.getElementById(cfg.mount || 'map-frame');
      if (frame) frame.appendChild(svg);

      // Only now: the wheel listener lives on the frame, so it needs the svg
      // to actually be in the document first.
      bindGestures();

      paint();
      syncAllRows();
      bindSidebar();
      applyView();
      emit();
      return api;
    },
  };

  window.QMap = api;
})();
